def _detect_severe_clashes(disruptors: list[Any]) -> tuple[list[Any], set[str]]:
    severe_clashes: list[Any] = []
    severe_clash_branches: set[str] = set()
    for d in disruptors:
        d_type = d.vector
        severity = 0.0
        if d.impact and d.impact.items:
            for item in d.impact.items:
                if item.key == 'friction':
                    severity = item.value
                    break
        d_severity = severity
        d_branches = d.actors
        if d_type in ('Chong', 'TombOpen') and d_severity >= 15.0:
            severe_clashes.append(d)
            for b in d_branches:
                if b:
                    severe_clash_branches.add(b)
    return (severe_clashes, severe_clash_branches)

